S.pv.forEach(p=>{if(p.o)return;c.g+=5+((p.up||{}).mkt?8:0);c.f+=(p.up||{}).gran?6:0;u+=tot(p.a);p.b.forEach(b=>{if(!b||b.cn)return;const d=BD[b.t];
if(d.r){let q=d.o*b.w*b.l*(1+.15*(S.pk[PK[d.r]]||0))*WG[S.wg][1]*(p.sp==d.r?1.8:1)*((p.up||{}).road?1.2:1)*(1+.1*((p.cl||1)-1))*(S.md>70?1.1:S.md<30?.8:1)*(d.r=='g'?TX[S.tx][1]:1);if(d.in){let f=1;for(const k in d.in)f=Math.min(f,(S.r[k]+c[k])/(d.in[k]*q||1));q*=Math.max(0,Math.min(1,f));for(const k in d.in)c[k]-=d.in[k]*q}c[d.r]+=q}
if(b.t=='sk')c.xp+=2*b.w*b.l;c.g-=1.5*b.l})});
