function tabs(){return'<div class="tabs">'+[['prov','🏞️ Provincie'],['city','🏘️ Město'],['army','⚔️ Armáda'],['eco','📈 Ekonomika'],['trade','💱 Trh'],['people','😊 Lid'],['gr','📊 Grafy']].map(([k,n])=>`<button class='${(S.tab||'prov')==k?'pri':''}' onclick='S.tab="${k}";render()'>${n}</button>`).join('')+'</div>'}
function pane(){const p=S.pv[S.sel],t=S.tab||'prov';if(t=='eco')return eco();if(t=='trade')return trade();if(t=='gr')return gr();if(t=='people')return people();if(p.o!=0)return pane0();return t=='army'?armyP(p):t=='city'?cityP(p):vw(p)+bl(p)}
function bl(p){const s=S.ps,b=s!=null&&p.b[s],idle=S.wk-asg();if(!b)return`<small>Volní pracovníci: ${idle} z ${S.wk}. Vyber místo pro stavbu nebo správu.</small>`;
const d=BD[b.t],cap=2+b.l,uc=sc(d.c,b.l),rq=b.l==1?2:4;
return`<div class='row'><span>👷 ${idle} volných</span>${d.w?`<span><button onclick='wrk(${p.id},${s},-1)'>−</button> ${b.w}/${cap} <button onclick='wrk(${p.id},${s},1)' ${idle>0&&b.w<cap?'':'disabled'}>+</button></span>`:''}${b.l<3?`<button onclick='upg(${p.id},${s})' ${ok(uc)&&S.lv>=rq?'':'disabled'}>Vylepšit ${cs(uc)} (úr. ${rq})</button>`:''}</div>`}
