function dec(id){S.dk=S.dk||{};if(id=='tax'&&S.dk[id])return;const p=S.pv[S.sel];
if(id=='opt'){let n=S.wk-asg();while(n-->0){let best=null,bs=-1;S.pv.forEach(q=>q.o==0&&q.b.forEach(b=>{if(!b||!BD[b.t].w||b.w>=2+b.l)return;const d=BD[b.t],z=(d.r?d.o:.3)/(S.r[d.r||'g']+20);if(z>bs){bs=z;best=b}}));if(best)best.w++;else break}}
else if(id=='upg'){S.pv.forEach(q=>q.o==0&&q.b.forEach(b=>{if(!b||b.cn||b.l>=(b.t=='hr'?5:3)||S.lv<2*b.l)return;const k=sc(BD[b.t].c,b.l);if(ok(k)){pay(k);b.l++;S.xp+=10}}))}
else if(id=='sup'){for(let n=0;n<20&&S.r.f+calc().f<0&&S.r.g>=Math.ceil(S.pr.f*11.5);n++){S.r.g-=Math.ceil(S.pr.f*11.5);S.r.f+=10}}
else if(id=='sell'){for(const k of 'idkvmsl')while(S.r[k]>=60){S.r[k]-=10;S.r.g+=F(S.pr[k]*8.5)}}
else if(id=='hire'){const k=bulkHirePrice();if(housingFree()<5){lg('Potřebuješ 5 volných míst k bydlení.');render();return}if(S.r.g<k){lg('Na nábor pěti pracovníků nemáš dost zlata.');render();return}S.r.g-=k;S.wk+=5;lg('Najato 5 pracovníků se slevou 30 %.')}
else if(id=='merc'){if(p.o==0&&S.r.g>=90){S.r.g-=90;p.a.p+=6}else return}
else if(id=='pub'){if(S.r.d>=30&&S.r.k>=30){S.r.d-=30;S.r.k-=30;S.xp+=35}else return}
else if(id=='feast'){if(S.r.v>=6&&housingFree()>0){S.r.v-=6;S.wk++;S.xp+=20}else return}
else if(id=='tax'){S.r.g+=90;S.wk=Math.max(2,S.wk-2);fixW()}
if(id=='tax')S.dk[id]=1;render()}
