function hint(b){const a=b.getAttribute('onclick')||'',n=(a.match(/^(\w+)/)||[])[1],l=(a.match(/["']([^"']+)["']/)||[])[1];return H[n+':'+l]||H[n]||''}
function render(){const a=document.activeElement,id=a&&a.id,v=a&&a.value;render0();const e=id&&$(id);if(e){e.value=v;e.focus()}document.querySelectorAll('#app button').forEach(b=>{const t=hint(b);if(t)b.title=t})}
