if(S){const c=calc(),sg=n=>(n>=0?'+':'')+n,cnt=o=>S.pv.filter(p=>p.o==o).length;
h+=`<div id="top"><span class="chip">Kolo ${S.t}</span><span class="chip">🪙 ${S.r.g} (${sg(c.g)})</span><span class="chip">🌾 ${S.r.f} (${sg(c.f)})</span><span class="chip">⛓️ ${S.r.i} (${sg(c.i)})</span><span class="chip">🪵 ${S.r.d} (${sg(c.d)})</span><span class="chip">🪨 ${S.r.k} (${sg(c.k)})</span><span class="chip">🍷 ${S.r.v} (${sg(c.v)})</span><span class="chip">🍯 ${S.r.m} (${sg(c.m)})</span><span class="chip">🏖️ ${S.r.s} (${sg(c.s)})</span><span class="chip">🏹 ${S.r.z} (${sg(c.z)})</span><span class="chip">🔮 ${S.r.l} (${sg(c.l)})</span><span class="chip">${S.md>70?'😊':S.md<30?'😠':'😐'} Nálada ${Math.round(S.md)}</span><span class="chip">👥 ${S.wk}/${housing()}</span><span class="chip">👷 Volní: ${S.wk-asg()}</span><button onclick="hire()" ${S.r.g>=hirePrice()&&housingFree()>0?'':'disabled'}>Najmout (${hirePrice()}🪙)</button><span class="chip">⭐ Úr. ${S.lv} · ${S.xp}/${need()} XP</span><span class="chip" style="border-color:${col(0)}">Ty: ${cnt(0)}</span><span class="chip" style="border-color:${col(1)}">Rudí: ${cnt(1)}</span><span class="chip" style="border-color:${col(2)}">Fialoví: ${cnt(2)}</span><button class="pri" onclick="S.acc=0;endTurn()">Konec kola</button><button onclick="S.pa=!S.pa;render()">${S.pa?'⏱ Reálný čas: vypnut':'⏱ Reálný čas: zapnut'}</button><span style="flex:1 1 80px;height:6px;background:var(--bd);border-radius:3px"><i id="pb" style="display:block;height:6px;background:var(--ac);width:0"></i></span></div>
<div id="main"><div id="map">${S.pv.map(p=>`<button class="c ${S.sel==p.id?'s':''}" style="border-color:${col(p.o)};background:linear-gradient(160deg,${TB[p.ty]},#ffffff90)" onclick="sel(${p.id})">${tile(p)}<b>${p.n}</b><small>${ico[p.sp]}+ ${ico[p.bn]}✗ ${TY[p.ty][0]}${p.o>0?' · '+OW[p.o].n:''}</small><span>${army(p.a)}</span><span>${p.o==0?p.b.map(b=>b?BD[b.t].ic+b.l:'▫️').join(' '):hrL(p)?'🏰'+hrL(p):''}</span></button>`).join('')}</div><div id="side">${tabs()}${pane()}</div></div><div id="log"><div id="hint" style="color:var(--ac);min-height:18px">Najeď myší na tlačítko pro krátký popis.</div>${S.lg.slice(0,3).map(l=>'<div>'+l+'</div>').join('')}</div>`}
