// Revised economy and presentation
Object.assign(RN,{c:'Uhlí',t:'Látky',a:'Brnění',h:'Koně'});
Object.assign(ico,{c:'⚫',t:'🧵',a:'🛡️',h:'🐎'});
Object.assign(PB,{c:4,t:7,a:16,h:12});Object.assign(GC,{c:'#444',t:'#a85599',a:'#778899',h:'#925d32'});
Object.assign(BD,{uhli:{n:'Uhelný důl',ic:'⚫',r:'c',o:4,w:1,c:{g:55,d:10}},tkal:{n:'Tkalcovna',ic:'🧵',r:'t',o:3,w:1,in:{f:1},c:{g:65,d:15}},zbroj:{n:'Platnéřství',ic:'🛡️',r:'a',o:2,w:1,in:{i:1,c:1},c:{g:90,k:15}},staj:{n:'Hřebčín',ic:'🐎',r:'h',o:2,w:1,in:{f:2},c:{g:70,d:20}}});
Object.assign(PD,{les:['Lesní hospodářství','+25 % dřeva'],prum:['Průmyslové cechy','+20 % zpracování'],log:['Logistika','−15 % spotřeby armády'],stav:['Stavitelství','−10 % ceny staveb'],vyc:['Vojenská akademie','+4 výcviky za kolo'],lid:['Sociální reformy','+8 cílové nálady'],tez:['Geologie','+20 % těžby'],dan:['Daňová správa','+20 % základních daní']});
const keys=Object.keys(RN), raw=['f','i','d','k','v','m','s','c'];
const oldInit=init;init=function(d){oldInit(d);for(const k of keys){S.r[k]??=0;if(k!='g')S.pr[k]=PB[k]}S.r.d=65;S.r.k=40;S.r.f=85;S.r.g=450;S.wk=8;S.pv.forEach(p=>{p.sp=raw[p.id%raw.length];p.bn=raw[(p.id+4)%raw.length]});let p=S.pv[12];p.sp='d';p.bn='s';p.b[3]={t:'pila',l:1,w:2,cn:0};render()};
function calc(){let c=Object.fromEntries(keys.map(k=>[k,0]));c.xp=0;let u=0, jobs=[];for(const p of S.pv){if(p.o!==0)continue;u+=tot(p.a);c.g+=(5*(1+.2*(S.pk.dan||0))*TX[S.tx][1])+((p.up||{}).mkt?8:0);c.f+=(p.up||{}).gran?6:0;for(const b of p.b){if(!b||b.cn)continue;const d=BD[b.t];c.g-=1.5*b.l;if(b.t==='sk')c.xp+=2*b.w*b.l;if(!d.r||!b.w)continue;let q=d.o*b.w*b.l*WG[S.wg][1]*(p.sp===d.r?1.8:1)*((p.up||{}).road?1.2:1)*(1+.1*((p.cl||1)-1))*(S.md>70?1.1:S.md<30?.8:1)*(1+.15*(S.pk[PK[d.r]]||0));if(d.r==='d')q*=1+.25*(S.pk.les||0);if(['i','k','s','c'].includes(d.r))q*=1+.2*(S.pk.tez||0);if(d.r==='g')q*=TX[S.tx][1];if(d.in)jobs.push([d,q*(1+.2*(S.pk.prum||0))]);else c[d.r]+=q;}}
for(const [d,q] of jobs){let n=q;for(const k in d.in)n=Math.min(n,Math.max(0,S.r[k]+c[k])/d.in[k]);for(const k in d.in)c[k]-=n*d.in[k];c[d.r]+=n}let m=Math.max(.4,1-.15*(S.pk.log||0));c.f-=S.wk+u*.5*m;c.g-=u*.3*m+S.wk*WG[S.wg][2]*.5+S.debt*.06;c.v-=Math.min(S.r.v+c.v,S.wk*.15);c.m-=Math.min(S.r.m+c.m,S.wk*.1);c.l-=Math.min(S.r.l+c.l,S.wk*.08);for(const k of keys)c[k]=Math.round(c[k]*100)/100;return c}
const oldEnd=endTurn;endTurn=function(){if(!S||modal())return;oldEnd();for(const k of keys)S.r[k]=Math.max(0,Math.round(S.r[k]*100)/100);render()};
const oldMood=mood;mood=function(){let m=oldMood();m.t=Math.min(100,m.t+8*(S.pk.lid||0));return m};
function bc(t){return sc(BD[t].c,Math.max(.5,1-.1*(S.pk.stav||0)))}
function can(p,t){const d=BD[t];return p.o===0&&ok(bc(t))&&d.r!==p.bn&&!(['hr','kas'].includes(t)&&p.b.some(b=>b&&b.t===t))&&(!d.req||S.pv.some(q=>q.o===0&&q.b.some(b=>b&&b.t===d.req&&!b.cn)))}
function build(i,s,t){const p=S.pv[i];if(p.b[s]||!can(p,t))return;pay(bc(t));p.b[s]={t,l:1,w:BD[t].w&&S.wk>asg()?1:0,cn:2};S.xp+=10;render()}
function tq(k,d){let p=Math.max(1,Math.round(S.pr[k]*pm(k))),n=Math.max(0,Math.floor(Number(S.q?.[k])||0));if(!Number.isFinite(n))return;if(d>0){let m=Math.min(d===2?Infinity:n,Math.floor(S.r.g/(p*1.15)));S.r.g-=Math.ceil(p*1.15*m);S.r[k]+=m}else{let m=Math.min(d===-2?S.r[k]:n,S.r[k]);S.r[k]-=m;S.r.g+=Math.floor(p*.85*m)}render()}
function trade(){return '<h3>Obchod se surovinami</h3>'+keys.filter(k=>k!=='g').map(k=>`<div class="row"><b>${ico[k]} ${RN[k]} · ${S.r[k]}</b><small>${Math.round(S.pr[k])} zl./ks</small><span><input type="number" min="0" style="width:65px" value="${S.q?.[k]||''}" oninput="(S.q=S.q||{}).${k}=this.value"><button onclick="tq('${k}',1)">Koupit</button><button onclick="tq('${k}',-1)">Prodat</button></span></div>`).join('')}
const oldEco=eco;eco=function(){let c=calc();return '<h3>Bilance říše / kolo</h3>'+keys.map(k=>`<div class="row"><span>${ico[k]} ${RN[k]} · sklad ${S.r[k]}</span><b style="color:${c[k]<0?'#d66':'#659b52'}">${c[k]>=0?'+':''}${c[k]}</b></div>`).join('')+oldEco()+`<h3>Nová rozhodnutí</h3><div class="g2"><button onclick="extra('reserve')">Nakoupit zásoby · 50 zl. → 20 jídla</button><button onclick="extra('industry')">Průmyslová zakázka · 10 látek → 100 zl.</button><button onclick="extra('recruit')">Těžká pěchota · 5 brnění + 40 zl. → 8 pěšáků</button><button onclick="extra('horse')">Jízdní oddíl · 5 koní + 50 zl. → 5 jezdců</button></div>`};
function extra(k){let p=S.pv[S.sel];if(S.dk?.[k])return;let costs={reserve:{g:50},industry:{t:10},recruit:{a:5,g:40},horse:{h:5,g:50}};if(!ok(costs[k])||(['recruit','horse'].includes(k)&&p.o!==0))return;pay(costs[k]);if(k==='reserve')S.r.f+=20;if(k==='industry')S.r.g+=100;if(k==='recruit')p.a.p+=8;if(k==='horse')p.a.j+=5;(S.dk=S.dk||{})[k]=1;lg('Rozhodnutí provedeno.');render()}
const oldRec=recN;recN=function(i,u,n){let p=S.pv[i],b=p.b.find(b=>b&&b.t==='kas'&&!b.cn);if(p.o!==0||!b||S.lv<UD[u].lv)return;let c=sc(UD[u].c,Math.max(.4,1-.15*(S.pk.sl||0)));for(let j=0;j<n&&p.rc<12*b.l+4*(S.pk.vyc||0)&&ok(c);j++){pay(c);p.a[u]++;p.rc++}render()};
function art(p,detail=false){let g=`<svg viewBox="0 0 320 220" preserveAspectRatio="xMidYMid meet"><rect width="320" height="220" fill="#9cb7a4"/><path d="M0 65L55 15 100 65 160 5 220 65 270 25 320 65V220H0" fill="#758e79"/><path d="M0 90Q100 45 180 90T320 80V220H0" fill="#76944f"/><path d="M0 180L320 105M0 95L320 205" stroke="#c5ae83" stroke-width="12"/>`;for(let i=0;i<12;i++){let x=25+i%4*74,y=48+Math.floor(i/4)*55,b=p.b[i],show=b||p.o!==0&&i<6;g+=`<g ${detail?`class="pl" onclick="ps(${i})"`:''}><ellipse cx="${x+24}" cy="${y+39}" rx="29" ry="12" fill="#283b2538"/>`;if(show){let color=b?.cn?'#c6a14d':'#d9c39b';g+=`<path d="M${x} ${y+17}l25 -10 25 10v25l-25 10 -25 -10Z" fill="${color}" stroke="#65503a"/><path d="M${x+25} ${y+7}l25 10v25l-25 10Z" fill="#a18a68"/><path d="M${x-4} ${y+17}l29 -22 29 22 -29 12Z" fill="${b?.cn?'#b59a51':'#864b3b'}" stroke="#563a30"/><rect x="${x+10}" y="${y+29}" width="7" height="13" fill="#493d30"/><text x="${x+34}" y="${y+38}" font-size="13">${b?BD[b.t].ic:''}</text>`}else if(detail)g+=`<rect x="${x}" y="${y+8}" width="50" height="38" rx="5" fill="#b5c69a" stroke="${S.ps===i?'#fff':'#536c42'}" stroke-dasharray="4 3"/><text x="${x+25}" y="${y+33}" text-anchor="middle" fill="#34482b">+</text>`;g+='</g>'}return g+`<rect x="8" y="7" width="304" height="205" rx="8" fill="none" stroke="${col(p.o)}" stroke-width="${hrL(p)?5:2}"/><text x="15" y="24" font-size="13" fill="#fff" stroke="#263b30" paint-order="stroke" stroke-width="3">${p.n} · ${ico[p.sp]} + · ⚔ ${tot(p.a)}</text></svg>`}
function tile(p){return art(p)}
function vw(p){return `<div class="row"><b>${p.n} · ${TY[p.ty][0]}</b><span>${RN[p.sp]} +80 % · bez ${RN[p.bn]}</span></div>`+art(p,true)+foc(p)+`<small>Výstavba trvá 2 kola. Hotová budova potřebuje pracovníky. Zpracování spotřebovává vstupy ze společného skladu.</small>`}
const oldRender=render;render=function(){oldRender();if(!S)return;let top=$('top');if(top){let c=calc();let chips=top.querySelectorAll('.chip');for(let i=1;i<=10;i++){let k=keys[i-1];chips[i].textContent=`${ico[k]} ${RN[k]} ${S.r[k]} (${c[k]>=0?'+':''}${c[k]})`}for(const k of ['c','t','a','h']){let e=document.createElement('span');e.className='chip';e.textContent=`${ico[k]} ${RN[k]} ${S.r[k]} (${c[k]>=0?'+':''}${c[k]})`;top.appendChild(e)}}};
render();


// Version 4: integer economy, paged interface and diplomacy
const calc3=calc;calc=function(){let c=calc3();for(const k of keys)c[k]=Math.round(c[k]||0);return c};
const render3=render;render=function(){if(S){for(const k of keys)S.r[k]=Math.max(0,Math.round((S.r[k]||0)*100)/100);for(const k in S.pr)S.pr[k]=Math.max(1,Math.round(S.pr[k]||PB[k]||1));}render3();paginate()};
const init3=init;init=function(d){init3(d);S.dip={1:{rel:0,until:0},2:{rel:0,until:0}};S.pg=0;render()};
function dip(k){return (S.dip||={})[k]|| (S.dip[k]={rel:0,until:0})}
function peace(k){return k>0&&dip(k).until>S.t}
function diplomacy(){return '<h3>Diplomacie říší</h3><p>Vztahy ovlivňují přijetí smluv. Příměří platí oboustranně.</p>'+[1,2].map(k=>{let d=dip(k),alive=S.pv.some(p=>p.o===k);return `<section class="dipcard"><b style="color:${col(k)}">${OW[k].n}</b> · vztahy ${d.rel}/100 · ${peace(k)?'Příměří do kola '+d.until:'Bez smlouvy'}${!alive?' · poraženi':''}<div class="g2">${[['gift','Dar 40 zlata (+25 vztahy)'],['peace','Příměří na 8 kol (60 zlata)'],['trade','Obchodní smlouva (30 zlata)'],['war','Zrušit smlouvy (−30 vztahy)']].map(([a,n])=>`<button onclick="dipAct(${k},'${a}')" ${!alive?'disabled':''}>${n}</button>`).join('')}</div><small>${d.trade?'Obchodní smlouva: +6 zlata za kolo.':''}</small></section>`}).join('')}
function dipAct(k,a){let d=dip(k);if(!S.pv.some(p=>p.o===k))return;if(a==='gift'&&ok({g:40})){pay({g:40});d.rel=Math.min(100,d.rel+25)}else if(a==='peace'&&!peace(k)&&d.rel>=25&&ok({g:60})){pay({g:60});d.until=S.t+8;lg('Příměří s '+OW[k].n+' uzavřeno.')}else if(a==='trade'&&!d.trade&&d.rel>=50&&ok({g:30})){pay({g:30});d.trade=true}else if(a==='war'){d.until=0;d.trade=false;d.rel=Math.max(-100,d.rel-30)}else{lg('Smlouva odmítnuta: potřebuješ dost zlata a vztahy 25 / 50, případně smlouva již platí.')}render()}
const calc4=calc;calc=function(){let c=calc4();for(const k of [1,2])if(S.dip?.[k]?.trade&&S.pv.some(p=>p.o===k))c.g+=6;return c};
