paginate=function(){let side=$('side');if(!side)return;let tab=side.querySelector('.tabs');if(!tab)return;let sig=[S.tab||'prov',S.sel,S.ps,S.tg,S.buildMode].join(':');if(sig!==pageSignature){pageSignature=sig;pageIndex=0}let nodes=[...side.childNodes].filter(n=>n!==tab);nodes.forEach(n=>n.remove());let body=document.createElement('div'),footer=document.createElement('div');body.className='pagebody';footer.className='pagefoot';footer.innerHTML='<button>◀ Předchozí</button><b>Strana</b><button>Další ▶</button>';side.append(body,footer);let fixed=nodes.filter(n=>n.nodeType===1&&n.matches('.buildnav'));if(fixed.length){let header=nodes[0];side.insertBefore(header,body);side.insertBefore(fixed[0],body);nodes=nodes.filter(n=>n!==header&&n!==fixed[0])}let units=[];for(let n of nodes){if(n.nodeType===1&&n.matches('.g2,.g3')){for(let child of [...n.children]){let wrap=document.createElement('div');wrap.className='pageunit';wrap.append(child);units.push(wrap)}}else if(n.nodeType!==3||n.textContent.trim())units.push(n)}let pages=[[]];for(let n of units){body.append(n);if(body.scrollHeight>body.clientHeight+2&&pages[pages.length-1].length){n.remove();body.replaceChildren();pages.push([]);body.append(n)}pages[pages.length-1].push(n)}body.replaceChildren();pageIndex=Math.max(0,Math.min(pageIndex,pages.length-1));body.append(...pages[pageIndex]);footer.children[0].disabled=pageIndex===0;footer.children[2].disabled=pageIndex===pages.length-1;footer.children[1].textContent=`Strana ${pageIndex+1} / ${pages.length}`;footer.children[0].onclick=()=>{pageIndex--;render()};footer.children[2].onclick=()=>{pageIndex++;render()}};
