function castleArt(x,y,c,id){let g=`<g transform="translate(${x} ${y})"><ellipse cy="20" rx="45" ry="19" fill="#19251c" opacity=".48"/>`;function tower(a,b,w,h){return `<g transform="translate(${a} ${b})"><path d="M0 0L${w} -5V${-h}L0 ${-h+5}Z" fill="#c8bba0" stroke="#554d40"/><path d="M${w} -5l8 5v${-h+5}l-8 -5Z" fill="#827968" stroke="#554d40"/><path d="M-3 ${-h+5}L${w/2+3} ${-h-18} ${w+11} ${-h} ${w} ${-h+5}Z" fill="${c}" stroke="#413b32"/><path d="M3 ${-h+15}h4v8H3Z" fill="#38372e"/>${Array.from({length:4},(_,i)=>`<path d="M0 ${-i*6-3}l${w} -5" stroke="#756c5c" opacity=".45"/>`).join('')}</g>`}g+=tower(-12,1,20,42)+tower(15,9,13,29)+tower(-31,13,14,28);g+=`<path d="M-32 10L-5 22 32 8V24L-5 37 -32 25Z" fill="#b2a58a" stroke="#5d5545"/><path d="M-32 10L-5 22 32 8" fill="none" stroke="#e4d5b3" stroke-width="4"/><path d="M-10 35V27Q-5 19 0 26V33" fill="#332d26"/><path d="M0 -60V-79l20 5 -20 6" fill="${c}" stroke="#342e28"/>`;return g+'</g>'}
